//! Raw FFI to the Zant native layer. Generated by `scripts/gen_bindings.sh`
//! (bindgen) from `src/renderer/skia/skia_bridge.h`, `src/platform/platform.h`
//! and `src/platform/pdf.h`; the results are checked in, so users need no
//! libclang. Everything here is `unsafe` FFI — use the safe wrappers in the
//! `zant` crate instead.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]

pub mod pdf;
pub mod platform;
pub mod skia;

/// Windows: the ICU data and the STIX Two Math font embedded in the executable
/// (generated by `build.rs`). `static_data::install()` must run before
/// `skia::zant_skia_init()`. macOS links both into Skia's own archives.
#[cfg(windows)]
pub mod static_data {
    include!(concat!(env!("OUT_DIR"), "/static_data.rs"));
}

/// One-time Skia initialisation, plus the embedded data on Windows.
///
/// Zig calls `zant_skia_init()` from the renderer wrapper
/// (`src/renderer/renderer.zig`); the Rust safe layer (`zant::renderer`) calls
/// this instead so the Windows static data is always installed first.
pub fn init() {
    #[cfg(windows)]
    static_data::install();
    // SAFETY: idempotent Skia initialisation; safe to call repeatedly per the
    // header.
    unsafe {
        skia::zant_skia_init();
    }
}
